class Solution:
    def longestEvenStretch(self, bits: List[int]) -> int:
        n, best = len(bits), 0
        for i in range(n):
            balance = 0
            for j in range(i, n):
                balance += 1 if bits[j] else -1
                if balance == 0:
                    best = max(best, j - i + 1)
        return best

