class Solution {
    public int longestEvenStretch(int[] bits) {
        int n = bits.length, best = 0;
        for (int i = 0; i < n; i++) {
            int balance = 0;
            for (int j = i; j < n; j++) {
                balance += bits[j] == 1 ? 1 : -1;
                if (balance == 0) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }
}

