class Solution {
    public int longestEvenStretch(int[] bits) {
        int n = bits.length;
        int[] first = new int[2 * n + 1];
        Arrays.fill(first, -2);
        first[n] = -1;
        int best = 0, balance = 0;
        for (int i = 0; i < n; i++) {
            balance += bits[i] == 1 ? 1 : -1;
            if (first[balance + n] != -2) best = Math.max(best, i - first[balance + n]);
            else first[balance + n] = i;
        }
        return best;
    }
}

