int longestEvenStretch(int* bits, int bitsSize) {
    int n = bitsSize;
    int* first = malloc((2 * n + 1) * sizeof(int));
    for (int k = 0; k <= 2 * n; k++) first[k] = -2;
    first[n] = -1;
    int best = 0, balance = 0;
    for (int i = 0; i < n; i++) {
        balance += bits[i] == 1 ? 1 : -1;
        if (first[balance + n] != -2) {
            if (i - first[balance + n] > best) best = i - first[balance + n];
        } else {
            first[balance + n] = i;
        }
    }
    free(first);
    return best;
}
